function apiErrorMessage(body,status){const code=typeof body?.error==='string'?body.error:body?.error?.code;return code==='INVALID_KEYWORD'?'検索キーワードを確認してください。':code==='NO_RESULTS'?'検索結果がありません。':status===401||status===403?'楽天APIの認証または利用条件を確認してください。':'楽天APIから情報を取得できませんでした。'}
async function searchRakutenHotels(){const status=$('rakuten-search-status'),results=$('rakuten-search-results'),keyword=$('rakuten-search-keyword').value.trim();if(!rakutenSettings.applicationId||!rakutenSettings.accessKey){status.textContent='先にバックアップ・設定で楽天API設定を保存してください。';return}if(keyword.length<2||keyword.length>50){status.textContent='検索キーワードは2〜50文字で入力してください。';return}status.textContent='検索中...';results.innerHTML='';const params=new URLSearchParams({applicationId:rakutenSettings.applicationId,accessKey:rakutenSettings.accessKey,keyword,format:'json'});if(rakutenSettings.affiliateId)params.set('affiliateId',rakutenSettings.affiliateId);try{const response=await fetch(`${RAKUTEN_ENDPOINT}?${params}`),body=await response.json();if(!response.ok){status.textContent=apiErrorMessage(body,response.status);return}const hotels=Array.isArray(body?.hotels)?body.hotels:[],items=hotels.map(entry=>{const basic=entry?.hotel?.[0]?.hotelBasicInfo;return basic&&typeof basic==='object'?basic:null}).filter(Boolean).slice(0,10);if(!items.length){status.textContent='検索結果がありません。';return}status.textContent=`${items.length}件見つかりました。`;results.innerHTML=items.map((hotel,index)=>'<article class="card"><h3>'+esc(hotel.hotelName||'施設名未取得')+'</h3><p>'+esc([hotel.address1,hotel.address2].filter(Boolean).join(' '))+'</p><p>'+esc(hotel.hotelSpecial||'')+'</p><p><strong>楽天API参考料金：</strong>'+fmt(hotel.hotelMinCharge)+'円</p><p class="muted">取得時点の最安値の目安です。予約時の料金を保証するものではありません。</p><button class="primary" type="button" data-rakuten-index="'+index+'">この施設を使う</button></article>').join('');results.querySelectorAll('[data-rakuten-index]').forEach(button=>button.addEventListener('click',()=>applyRakutenHotel(items[Number(button.dataset.rakutenIndex)])))}catch(error){status.textContent=error instanceof TypeError?'ブラウザから楽天APIへ接続できませんでした。':'楽天APIから情報を取得できませんでした。'}}
