function saleDateParts(text){return String(text||'').match(/(20\d{2})[\/\-年](\d{1,2})[\/\-月](\d{1,2})/g)||[]}
function saleIsActive(s){const parts=saleDateParts(s.bookingPeriod);if(parts.length<2)return false;const parse=v=>new Date(v.replace('年','/').replace('月','/').replace('日',''));const dates=parts.map(parse).filter(v=>!Number.isNaN(v.getTime()));return dates.length>=2&&dates[0]<=new Date()&&new Date()<=dates[dates.length-1]}
function filteredSales(){const keyword=($('saved-sale-keyword')?.value||'').trim().toLowerCase(),region=($('saved-sale-region')?.value||'').trim().toLowerCase(),status=$('saved-sale-status')?.value||'all';return state.sales.filter(s=>{const hay=[s.name,s.discountText,s.conditions,s.notes].join(' ').toLowerCase();return(!keyword||hay.includes(keyword))&&(!region||String(s.region||'').toLowerCase().includes(region))&&(status==='all'||status===s.confirmStatus||(status==='active'&&saleIsActive(s)))})}
