document.addEventListener('click',e=>{if(e.target.id==='research-prompt-copy'){e.preventDefault();e.stopImmediatePropagation();const value=$('research-prompt')?.value||'';if(value)copyTextWithFeedback(value,{status:$('research-prompt-status')});else $('research-prompt-status').textContent='先にプロンプトを作成してください。'}if(e.target.classList?.contains('copy')){e.preventDefault();e.stopImmediatePropagation();const id=e.target.dataset.id,c=state.candidates.find(x=>x.id===id);if(!c)return;sync(id);copyTextWithFeedback(drafts[id]?.[e.target.dataset.tcopy]||'',{status:$('notice')})}},true);
const renderSavedPostWithSavedDraft=renderSavedPost;renderSavedPost=function(c){const hadDraft=Boolean(drafts[c.id]);renderSavedPostWithSavedDraft(c);if(!hadDraft&&c.post&&typeof c.post==='object'){drafts[c.id]={...drafts[c.id],body:c.post.body||'',reply1:c.post.reply1||'',reply2:c.post.reply2||'',focus:c.focus||drafts[c.id].focus,tone:c.tone||drafts[c.id].tone,format:c.format||drafts[c.id].format};document.querySelectorAll('[data-t][data-id="'+c.id+'"]').forEach(field=>{if(Object.prototype.hasOwnProperty.call(drafts[c.id],field.dataset.t))field.value=drafts[c.id][field.dataset.t]||''})}};compose=renderSavedPost;

const FLYER_ANGLES=[['balanced','お得＋宿の魅力'],['meal','食事重視'],['onsen','温泉重視'],['pet','ペット旅行向け']];
const FLYER_RATIOS=[['1:1','1:1　SNS正方形'],['4:5','4:5　SNS縦長'],['9:16','9:16　Threads / Stories向け縦長']];
const FLYER_DESIGNS=[['travel_ad','旅行広告風'],['luxury','上品・高級感'],['friendly','やさしい・親しみやすい'],['simple','シンプル・読みやすい']];
function flyerTextFacts(c,angle){const data=confirmedPostingData(c),base={balanced:uniqueFactParts([data.attraction,data.features,data.meal,data.onsen,data.facilities],4),meal:uniqueFactParts([data.meal,data.attraction,data.onsen,data.features],4),onsen:uniqueFactParts([data.onsen,data.attraction,data.meal,data.features],4),pet:uniqueFactParts([data.features,data.facilities,data.attraction,data.meal,data.onsen],4)}[angle]||[];return {data,highlights:base}}
function buildFlyerPrompt(c,settings){const {data,highlights}=flyerTextFacts(c,settings.angle),ratio=FLYER_RATIOS.find(x=>x[0]===settings.aspectRatio)?.[1]||settings.aspectRatio,design=FLYER_DESIGNS.find(x=>x[0]===settings.design)?.[1]||settings.design,angle=FLYER_ANGLES.find(x=>x[0]===settings.angle)?.[1]||settings.angle,lines=[data.name,data.area, data.campaign&&data.discount?[data.campaign,data.discount].join('：'):data.discount||'',...highlights,priceIsSafeForPost(data)?'料金：'+fmt(data.price)+(data.priceCondition?'（'+data.priceCondition+'）':''):'',data.conditions?'※'+uniqueFactParts([data.conditions],1)[0]:'','PR'].filter(Boolean);return ['楽天トラベルの宿泊情報を紹介するSNS向け旅行広告画像を作成してください。','【見せ方】'+angle,'【画像比率】'+ratio,'【画像内テキスト】',lines.join('\n'),'【ビジュアル指示】',design+'の旅行広告。保存されたFACTから確認できる魅力を中心に、情報を詰め込みすぎず読みやすく配置してください。宿名・地域・料理・温泉・ペット対応など、入力されている内容だけを使用してください。','【重要】','FACTとデザイン指示を混同せず、数字・名称・条件を書き換えないでください。「最大30%OFF」を「30%OFF」や「全プラン30%OFF」に変更しないでください。入力されていない設備・料理・客室・景観・サービスを追加しないでください。生成された背景・人物・料理・温泉などは広告表現用のイメージであり、実在施設の正確な写真として表現しないでください。URLやQRコードは生成しないでください。日本語テキストを正確に描画し、生成後に人間が文字内容を確認してください。'].join('\n\n')}
function persistFlyer(c,settings,prompt){c.flyer={enabled:true,angle:settings.angle,aspectRatio:settings.aspectRatio,design:settings.design,prompt,updatedAt:new Date().toISOString()};localStorage.setItem(KEY,JSON.stringify(state))}
function flyerCard(c){const card=document.querySelector('[data-a="compose"][data-id="'+c.id+'"]')?.closest('article.card');return card}
function removeFlyerPanel(c){document.querySelector('#flyer-'+c.id)?.remove()}
function renderFlyerOffer(c){const card=flyerCard(c);if(!card||card.querySelector('[data-flyer-offer]')||c.flyer?.enabled)return;const area=card.querySelector('#compose-'+c.id);if(!area)return;area.insertAdjacentHTML('afterend','<div class="panel" data-flyer-offer="true"><h4>この旅行情報の紹介チラシも作りますか？</h4><p class="muted">保存済みFACTから、画像生成AIへ渡すプロンプトを作成できます。</p><div class="button-row"><button class="primary" type="button" data-a="flyer-open" data-id="'+c.id+'">紹介チラシを作る</button><button class="secondary" type="button" data-a="flyer-dismiss" data-id="'+c.id+'">作らない</button></div></div>')}
function renderFlyerUI(c){const card=flyerCard(c);if(!card)return;removeFlyerPanel(c);let panel=card.querySelector('#flyer-'+c.id);if(!panel){panel=document.createElement('div');panel.id='flyer-'+c.id;panel.className='panel';card.appendChild(panel)}const previous=c.flyer?.enabled?c.flyer:{};panel.innerHTML='<h4>紹介チラシ</h4><p class="muted">保存済みFACTを選別して、ChatGPTやGeminiへ貼り付けるプロンプトを作成します。画像生成APIは使用しません。</p><div class="grid three"><label>チラシの見せ方<select data-flyer="angle">'+FLYER_ANGLES.map(x=>'<option value="'+x[0]+'" '+(previous.angle===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></label><label>画像比率<select data-flyer="aspectRatio">'+FLYER_RATIOS.map(x=>'<option value="'+x[0]+'" '+(previous.aspectRatio===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></label><label>デザイン<select data-flyer="design">'+FLYER_DESIGNS.map(x=>'<option value="'+x[0]+'" '+(previous.design===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></label></div><div class="button-row"><button class="primary" type="button" data-a="flyer-generate" data-id="'+c.id+'">チラシ作成プロンプトを作る</button><button class="secondary" type="button" data-a="flyer-copy" data-id="'+c.id+'">プロンプトをコピー</button><button class="secondary" type="button" data-a="flyer-clear" data-id="'+c.id+'">クリア</button></div><textarea data-flyer="prompt" rows="18" placeholder="設定してプロンプトを作成してください">'+esc(previous.prompt||'')+'</textarea><p class="status" data-flyer-status role="status" aria-live="polite"></p><p class="muted">画像内の日本語、FACT、条件は生成後に人間が確認してください。</p>'}
function currentFlyerSettings(panel){return {angle:panel.querySelector('[data-flyer="angle"]')?.value||'balanced',aspectRatio:panel.querySelector('[data-flyer="aspectRatio"]')?.value||'4:5',design:panel.querySelector('[data-flyer="design"]')?.value||'travel_ad'}}
function flyerPanelFor(id){return document.querySelector('#flyer-'+id)}
document.addEventListener('click',e=>{const action=e.target.dataset.a,id=e.target.dataset.id;if(!id)return;const c=state.candidates.find(x=>x.id===id);if(!c)return;if(action==='ready'){setTimeout(()=>{if(c.status==='ready')renderFlyerOffer(c)},0)}if(action==='flyer-dismiss'){removeFlyerPanel(c);notice('紹介チラシは作成しませんでした。')}if(action==='flyer-open'){renderFlyerUI(c)}if(action==='flyer-generate'){const panel=flyerPanelFor(id);if(!panel)return;const settings=currentFlyerSettings(panel),prompt=buildFlyerPrompt(c,settings);panel.querySelector('[data-flyer="prompt"]').value=prompt;persistFlyer(c,settings,prompt);panel.querySelector('[data-flyer-status]').textContent='プロンプトを保存しました。FACTは変更していません。'}if(action==='flyer-copy'){const panel=flyerPanelFor(id);if(panel)copyTextWithFeedback(panel.querySelector('[data-flyer="prompt"]')?.value,{status:panel.querySelector('[data-flyer-status]')})}if(action==='flyer-clear'){const panel=flyerPanelFor(id);if(panel){panel.querySelector('[data-flyer="prompt"]').value='';panel.querySelector('[data-flyer-status]').textContent='';if(c.flyer){c.flyer.prompt='';c.flyer.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state))}}}},false);
const renderCandidatesWithFlyer=renderCandidates;renderCandidates=function(){renderCandidatesWithFlyer();state.candidates.filter(c=>c.flyer?.enabled).forEach(c=>{const card=flyerCard(c),actions=card?.querySelector('.card-actions');if(actions&&!actions.querySelector('[data-a="flyer-open"]'))actions.insertAdjacentHTML('beforeend','<button class="secondary" type="button" data-a="flyer-open" data-id="'+c.id+'">紹介チラシ</button>')})};render();
function generateFlyerShortPost(c,d){const data=confirmedPostingData(c),focus=d.focus||'balanced',hasUrl=Boolean(c.threadsShortUrl),focusFacts={deal:uniqueFactParts([data.discount,data.campaign,data.attraction],1),charm:uniqueFactParts([data.attraction,data.features,data.facilities],1),onsen:uniqueFactParts([data.onsen,data.attraction],1),meal:uniqueFactParts([data.meal,data.attraction],1),family:uniqueFactParts([data.attraction,data.features,data.meal],1),couple:uniqueFactParts([data.attraction,data.meal,data.onsen],1),solo:uniqueFactParts([data.attraction,data.onsen,data.meal],1),pet:uniqueFactParts([data.features,data.facilities,data.attraction],1),balanced:uniqueFactParts([data.attraction,data.features,data.onsen,data.meal],1),ai:uniqueFactParts([data.discount,data.attraction,data.features,data.onsen,data.meal],1)}[focus]||[];if(!focusAvailable(data,focus))return {body:data.name+'について、選択したテーマのFACTは未確認です。',reply1:'詳しい情報は公式ページでご確認ください。\n'+(hasUrl?c.threadsShortUrl:'Threads用URL未登録')+(hasUrl?'\nPR':''),reply2:''};const lead={deal:data.area+'のお得な宿情報をチェック。',charm:data.area+'で宿の魅力を楽しむ旅へ。',onsen:data.area+'で温泉を楽しむ旅へ。',meal:data.area+'で料理を楽しむ旅へ。',family:data.area+'で家族旅行を考えている方へ。',couple:data.area+'で二人の旅を考えている方へ。',solo:data.area+'で一人旅を考えている方へ。',pet:data.area+'で愛犬と楽しむ宿旅へ。',balanced:data.area+'で宿の魅力を楽しむ旅へ。',ai:data.area+'の旅行情報を短くまとめました。'}[focus];const strong=[data.discount||data.campaign,focusFacts[0]].filter(Boolean).join('。');const body=[data.name?data.name+'｜'+lead:lead,strong].filter(Boolean).join('\n').slice(0,120);const conditions=uniqueFactParts([data.conditions],1);const reply1=['詳しいプラン・空室はこちら👇',hasUrl?c.threadsShortUrl:'Threads用URL未登録',conditions.length?'※'+conditions[0]:'',hasUrl?'PR':''].filter(Boolean).join('\n');return {body,reply1,reply2:''}}
const generateSavedPostBeforeFlyer=generateSavedPost;generateSavedPost=function(c,d){return c.flyer?.enabled===true?generateFlyerShortPost(c,d):generateSavedPostBeforeFlyer(c,d)};
const renderSavedPostWithFlyerShortBody=renderSavedPost;renderSavedPost=function(c){renderSavedPostWithFlyerShortBody(c);if(c.flyer?.enabled!==true)return;const d=drafts[c.id]||{focus:'balanced',tone:'natural',format:'reply_link'},g=generateFlyerShortPost(c,d);drafts[c.id]={...d,...g};const body=document.querySelector('[data-t="body"][data-id="'+c.id+'"]'),reply1=document.querySelector('[data-t="reply1"][data-id="'+c.id+'"]');if(body)body.value=g.body;if(reply1)reply1.value=g.reply1};compose=renderSavedPost;
const renderSavedPostWithFlyerChoice=renderSavedPost;function renderFlyerChoice(c){const target=$('compose-'+c.id);if(!target)return;target.innerHTML='<div class="panel"><h3>投稿作成の準備</h3><p>紹介チラシを作りますか？</p><div class="button-row"><button class="primary" type="button" data-a="flyer-choice" data-choice="yes" data-id="'+c.id+'">紹介チラシを作る</button><button class="secondary" type="button" data-a="flyer-choice" data-choice="no" data-id="'+c.id+'">作らない</button></div></div>'}compose=renderFlyerChoice;
document.addEventListener('click',e=>{if(e.target.dataset.a!=='flyer-choice')return;const id=e.target.dataset.id,c=state.candidates.find(x=>x.id===id);if(!c)return;c.flyer={...(c.flyer||{}),enabled:e.target.dataset.choice==='yes'};drafts[id]={focus:c.focus||'balanced',tone:c.tone||'natural',format:c.format||'reply_link'};renderSavedPostWithFlyerChoice(c);if(e.target.dataset.choice==='yes')renderFlyerUI(c)});
function candidateRakutenOfficialUrl(c){const facts=c.chatgptResearchFacts&&typeof c.chatgptResearchFacts==='object'?c.chatgptResearchFacts:{};const hotel=facts.hotel&&typeof facts.hotel==='object'?facts.hotel:{};return [hotel.rakutenUrl,c.sourceUrl].map(value=>String(value||'').trim()).find(validHttpUrl)||''}
const renderCandidatesWithOfficialLink=renderCandidates;renderCandidates=function(){renderCandidatesWithOfficialLink();document.querySelectorAll('#candidate-list .card').forEach((card,index)=>{const url=candidateRakutenOfficialUrl(state.candidates[index]);if(!url||card.querySelector('[data-rakuten-official]'))return;const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.className='secondary';link.dataset.rakutenOfficial='true';link.textContent='楽天トラベルで確認 ↗';const warning=card.querySelector('.warning'),actions=card.querySelector('.card-actions');if(warning)warning.insertAdjacentElement('afterend',link);else if(actions)actions.insertAdjacentElement('beforebegin',link)})};render();
function isRakutenOfficialUrl(value){try{const url=new URL(String(value||''));const host=url.hostname.toLowerCase();return (url.protocol==='http:'||url.protocol==='https:')&&(host==='hotel.travel.rakuten.co.jp'||host==='travel.rakuten.co.jp'||host.endsWith('.travel.rakuten.co.jp'))}catch{return false}}
const normalizedChatGptImportBeforeRakutenUrlCheck=normalizedChatGptImport;normalizedChatGptImport=function(data){const facts=normalizedChatGptImportBeforeRakutenUrlCheck(data);if(facts.hotel)facts.hotel.rakutenUrl=isRakutenOfficialUrl(facts.hotel.rakutenUrl)?facts.hotel.rakutenUrl:'';return facts};
const useChatGptImportBeforeRakutenUrlPriority=useChatGptImport;useChatGptImport=function(f){useChatGptImportBeforeRakutenUrlPriority(f);const url=isRakutenOfficialUrl(f?.hotel?.rakutenUrl)?f.hotel.rakutenUrl:(f?.sources||[]).find(s=>isRakutenOfficialUrl(s?.url))?.url||'';if(url&&$('sourceUrl'))$('sourceUrl').value=url};
candidateRakutenOfficialUrl=function(c){const facts=c.chatgptResearchFacts&&typeof c.chatgptResearchFacts==='object'?c.chatgptResearchFacts:{},hotel=facts.hotel&&typeof facts.hotel==='object'?facts.hotel:{};return [hotel.rakutenUrl,c.sourceUrl].find(isRakutenOfficialUrl)||''};
document.addEventListener('click',e=>{if(e.target.dataset.a!=='edit')return;setTimeout(()=>{const c=state.candidates.find(x=>x.id===$('edit-id')?.value),url=candidateRakutenOfficialUrl(c||{});if(url&&$('sourceUrl'))$('sourceUrl').value=url},0)});
